create extension if not exists pgtap with schema extensions;
begin;
select no_plan();
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
update private.push_control set enabled=true,general_release=true;
select public.register_push_token_v1('web','calm-test-device',jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/calm','keys',jsonb_build_object('p256dh',repeat('A',87),'auth',repeat('B',22))));
update public.push_tokens set consented_at=now()-interval '1 hour' where device_key='calm-test-device';
update private.notification_preferences set timezone='UTC',quiet_start=((now() at time zone 'UTC')+interval '1 hour')::time,quiet_end=((now() at time zone 'UTC')+interval '2 hours')::time;
delete from private.push_jobs;
delete from public.notifications;
select private.notification_event('90000000-0000-4000-8000-000000000001','course_content','Lesson','/study','calm-lesson-1','academic','{"lesson_id":"22000000-0000-4000-8000-000000000001"}');
select private.notification_event('90000000-0000-4000-8000-000000000001','course_content','Lesson 2','/study','calm-lesson-2','academic','{"lesson_id":"22000000-0000-4000-8000-000000000002"}');
select is((select count(*)::int from public.notifications),1,'bulk lessons create one course summary');
select is((select (context->>'updates')::int from public.notifications),2,'summary counts grouped events');
select private.notification_event('90000000-0000-4000-8000-000000000001','course_content','Lesson 2 retry','/study','calm-lesson-2','academic','{"lesson_id":"22000000-0000-4000-8000-000000000002"}');
select is((select (context->>'updates')::int from public.notifications),2,'retries do not inflate grouped event count');
select is((select count(*)::int from private.push_jobs),1,'grouped update does not queue another push');
select public.claim_push_jobs_v1();
select ok((select public.authorize_push_job_v1(id,lease) is null from private.push_jobs limit 1),'course summary waits five minutes');
select ok((select available_at>=now()+interval '5 minutes' from private.push_jobs limit 1),'batching deadline persisted');
update public.notifications set created_at=now()-interval '6 minutes';
update private.push_jobs set available_at=now();
select public.claim_push_jobs_v1();
select ok((select public.authorize_push_job_v1(id,lease) is not null from private.push_jobs limit 1),'ready course summary is authorized');
select is((select count(*)::int from private.push_delivery_windows),1,'device cooldown reserved');
select private.notification_event('90000000-0000-4000-8000-000000000001','test','Another alert','/home','calm-other','account');
select public.claim_push_jobs_v1();
select ok((select public.authorize_push_job_v1(j.id,j.lease) is null from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='calm-other'),'different category also observes cooldown');
select ok((select j.available_at>=now()+interval '30 minutes' and j.attempts=0 from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='calm-other'),'cooldown defers without spending retry budget');
update private.push_delivery_windows set next_at=now()-interval '1 second';
update private.push_jobs set available_at=now() where state='pending';
select public.claim_push_jobs_v1();
select ok((select public.authorize_push_job_v1(j.id,j.lease) is not null from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='calm-other'),'next alert allowed after cooldown');
select ok(not has_table_privilege('authenticated','private.push_delivery_windows','select'),'device cooldown state remains private');
select ok(not has_function_privilege('authenticated','public.authorize_push_job_v1(uuid,uuid)','execute'),'worker authorization stays restricted');
update public.enrollments set ended_at=now() where user_id='90000000-0000-4000-8000-000000000001';
select ok((select not private.push_relevant(n) from public.notifications n where kind='course_content'),'leaving course revokes relevance of grouped summary');
select finish();
rollback;
